/usr/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const source = fs.readFileSync('entry/src/main/ets/pages/OpenAppPage2.ets', 'utf8');
const marker = '.onClick(() => {';
const start = source.indexOf(marker);
if (start < 0) throw new Error('onClick callback not found');
const bodyStart = start + marker.length;
const end = source.indexOf('\\n              })', bodyStart);
if (end < 0) throw new Error('onClick callback terminator not found');
const body = source.slice(bodyStart, end).trim();
const checks = {
  callback_found: start >= 0,
  callback_body_non_empty: body.length > 0,
  starts_ability: body.includes('this.context.startAbility(wantInfo)'),
  success_log: body.includes(\"hilog.info(DOMAIN_NUMBER, TAG, 'startAbility success.')\"),
  failure_log: body.includes(\"hilog.error(DOMAIN_NUMBER, TAG, 'startAbility failed.')\"),
  balanced_braces: (body.match(/\\{/g) || []).length === (body.match(/\\}/g) || []).length
};
console.log(JSON.stringify(checks));
if ("'!Object.values(checks).every(Boolean)) process.exitCode = 1;
NODE'

